def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def minSwapsPerLevel(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    depth = [0] * n
    levels = []
    for k in range(n):
        d = depth[k]
        if d == len(levels):
            levels.append([])
        levels[d].append(vals[k])
        for c in (left[k], right[k]):
            if c != -1:
                depth[c] = d + 1
    total = 0
    for lv in levels:
        m = len(lv)
        order = sorted(range(m), key=lambda i: lv[i])
        seen = [False] * m
        for i in range(m):
            if not seen[i]:
                j = i
                length = 0
                while not seen[j]:
                    seen[j] = True
                    j = order[j]
                    length += 1
                total += length - 1
    return total
